import java.util.HashMap;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2022.03.01
 */
public class FieldStats
{
    // Counters for each type of entity (jaguar, gazelle, etc.) in the simulation.
    private HashMap<Class, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @param field The field currently occupied.
     * @param simulator. The current simulator the simulation is being run on.
     * @return A string listing what is in the field.
     */
    public String getPopulationDetails(Field field, Simulator simulator)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field, simulator);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one class of actor.
     * @param actor The object of animal to increment.
     * @param simulator. The current simulator the simulation is being run on.
     */
    public void incrementCount(Object actor, Simulator simulator)
    {
        Class animalClass = actor.getClass();
        Counter count = counters.get(animalClass);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(animalClass.getName());
            counters.put(animalClass, count);
        }
        count.increment();
        if (simulator.getSteps() != 0){
            if(actor instanceof Grass){
                count.setCount(simulator.getNoOfGrass());
            }
        }
    }

    /**
     * Indicate that an actor count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @param field The field currently occupied.
     * @param simulator The current simulator the simulation is being run on.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field, Simulator simulator)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field, simulator);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of all animals.
     * These are not kept up to date as all animals
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     * @param simulator The current simulator the simulation is being run on.
     */
    private void generateCounts(Field field, Simulator simulator)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    incrementCount(animal, simulator);
                }
            }
        }
        countsValid = true;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 2022.03.01
 */
public abstract class Plants extends Actor
{
    //private static final Random rand = Randomizer.getRandom();
    private int sunLevel; 
    private int waterLevel;
    /**
     * Create a new plant at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plants(Field field, Location location)
    {
        super(field,location);
        sunLevel = getRandom().nextInt(10) + 1;
        waterLevel = getRandom().nextInt(10) + 1;
    }


    /**
     * Generate a number representing how much a plant grows,if it can grow.
     * @return The number of squares it grows into(may be zero).
     */
    protected int growth(int step)
    {
        int births = 0;
        if(getAge() >= getBreedingAge() && getAge() % 2 == 0 ) {
            births = getRandom().nextInt(getMaxLitter()) + 1;
        }

        if(step > 1600){
            births = births + 20;
        }
        return births;
    }

    /**
     * Get growing age of a plant.
     * @return Growing age of the plant.
     */
    abstract protected int getBreedingAge();

    /**
     * Get the maximum number of squares the plant can grow into.
     * @return  The number of squares the plant can grow into.
     */
    abstract protected int getMaxLitter();  

    /**
     * Increase the current water level.
     */
    protected void increaseWaterLevel(){
        waterLevel++;
    }

    /**
     * Decrease the current water level.
     */
    protected void decreaseWaterLevel(){
        waterLevel--;
    }

    /**
     * Increase the current sun level.
     */
    protected void increaseSunLevel(){
        sunLevel++;
    }

    /**
     * Decrease the current sun level.
     */
    protected void decreaseSunLevel(){
        sunLevel--;
    }

    /**
     * Get the current water level.
     * @return The plants current water level.
     */
    protected int getWaterLevel(){
        return waterLevel;
    }

    /**
     * Get the current sun level.
     * @return The plants current sun level.
     */
    protected int getSunLevel(){
        return sunLevel;
    }

    /**
     * If either the water level or the sun level is 0 the plant dies.
     * @param step. The number of steps in the simulation.
     */
    protected void incrementAge(int step){
        super.incrementAge(step);
        if(waterLevel == 0 || sunLevel == 0){
            setDead();
        }
    }
}

